import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:chroniccare/domain/entities/check_in_entity.dart';import 'package:chroniccare/domain/entities/contact_entity.dart';import 'package:chroniccare/domain/entities/medication_entity.dart';import 'package:chroniccare/domain/entities/mood_entry_entity.dart';import 'package:chroniccare/domain/entities/report_history_entity.dart';import 'package:chroniccare/domain/entities/user_profile_entity.dart';import 'package:chroniccare/domain/logic/streak_calculator.dart';import 'package:chroniccare/presentation/providers/core_providers.dart';/// 用户档案（v0.16: domain entity, no longer Drift row）final userProfileProvider = StreamProvider<UserProfileEntity?>(  (ref) => ref.watch(userProfileRepositoryProvider).watch(),);/// 今天的打卡final todayCheckInProvider = StreamProvider<CheckInEntity?>(  (ref) => ref.watch(checkInRepositoryProvider).watchToday(),);/// 所有打卡（含 normal + temp + phq9 + gad7），用于趋势图final allCheckInsProvider = StreamProvider<List<CheckInEntity>>(  (ref) => ref.watch(checkInRepositoryProvider).watchAll(),);/// 所有 normal 类型打卡（用于计算 streak）final allNormalCheckInsProvider = StreamProvider<List<CheckInEntity>>(  (ref) {    return ref        .watch(checkInRepositoryProvider)        .watchAll()        .map((all) => all.where((c) => c.isNormal).toList());  },);/// 当前 streak + 是否断签（B8 fix: 在 build 顶部算一次）////// 之前 home_page 在 build 里调 [StreakCalculator.calculate] 3 次/// （鼓励文案 / 打卡按钮 / 是否断签），跨 23:59:59 时 streak 不一致。/// 提到 provider 后用 const now 注入，所有 widget 看到的是同一个值。class StreakSnapshot {  final int streak;  final bool shouldShowStreakBroken;  const StreakSnapshot({    required this.streak,    required this.shouldShowStreakBroken,  });}final streakSummaryProvider = Provider<AsyncValue<StreakSnapshot>>((ref) {  final async = ref.watch(allNormalCheckInsProvider);  return async.whenData((checkIns) {    final now = DateTime.now();    return StreakSnapshot(      streak: StreakCalculator.calculate(checkIns: checkIns, now: now),      shouldShowStreakBroken: StreakCalculator.shouldShowStreakBroken(        checkIns: checkIns,        now: now,      ),    );  });});/// 联系人列表final contactsProvider = StreamProvider<List<ContactEntity>>(  (ref) => ref.watch(contactRepositoryProvider).watchAll(),);/// 吃药列表（v0.13 Round 11: 返回 MedicationEntity，不直接暴露 Drift row）final medicationsProvider = StreamProvider<List<MedicationEntity>>(  (ref) => ref.watch(medicationRepositoryProvider).watchAll(),);/// 所有 medication 列表（含已停药，给"用药报告"用）////// 历史用药可能在窗口内有打卡记录，但 medication.isActive=false，/// 报告必须包含这些数据才能完整还原用户服药历史。（B3 fix）final allMedicationsProvider = StreamProvider<List<MedicationEntity>>(  (ref) {    final repo = ref.watch(medicationRepositoryProvider);    // v0.16: 新增 watchAllIncludingInactive() abstract method    return repo.watchAllIncludingInactive();  },);/// 所有评估记录（PHQ-9 / GAD-7，按时间正序）final assessmentsProvider = StreamProvider<List<CheckInEntity>>(  (ref) => ref.watch(checkInRepositoryProvider).watchAssessments(),);/// 报告历史（按生成时间倒序）— v0.16: 用 domain entityfinal reportHistoriesProvider = StreamProvider<List<ReportHistoryEntity>>(  (ref) => ref.watch(reportHistoryRepositoryProvider).watchAll(),);/// 今日情绪记录final todayMoodProvider = StreamProvider<List<MoodEntryEntity>>(  (ref) => ref.watch(moodRepositoryProvider).watchToday(),);/// 所有情绪记录final allMoodProvider = StreamProvider<List<MoodEntryEntity>>(  (ref) => ref.watch(moodRepositoryProvider).watchAll(),);